 "content": "def transform(grid):
    """Extend the interrupted horizontal bars along their aligned vertical gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Rows with substantial horizontal bars; record columns that are a one-cell
    # gap between matching colored parts of a bar.
    stripe_rows = [r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 5]
    events = {}
    for r in stripe_rows:
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                events.setdefault(c, []).append((r, color))

    for c, ev in events.items():
        ev.sort()
        last_r = ev[-1][0]
        # The lower vertical stem supplies the color below the final crossing.
        seed_color = next((grid[r][c] for r in range(last_r + 1, h) if grid[r][c]), None)
        if seed_color is None:
            continue
        for i, (r, color) in enumerate(ev):
            start = 0 if i == 0 else ev[i - 1][0] + 1
            # Each interval takes the color of its lower horizontal crossing.
            for rr in range(start, r + 1):
                out[rr][c] = color
        for rr in range(last_r + 1, h):
            out[rr][c] = seed_color
    return out

